// Assemble the Halden Row Interiors theme (6 Divi 5 pages for a boutique interior design studio) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php haldenrow     -> dist/theme-packs/haldenrow/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && HALDEN_DIR=<dir with the six json files> npx tsx scripts/create-halden-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.HALDEN_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/haldenrow';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Halden Row Interiors',
  tagline: 'Rooms that feel like you, only better.',
  audience: 'homeowners and small hotels who want a calm, layered, well-built interior and one designer who looks after the whole project',
  conversionGoal: 'book a consultation',
  primaryCta: 'Book a consultation',
  accentColorHex: '#C8A46A',
  voice: 'quiet, assured and plain-spoken. Short sentences, specific details, no hype and no design clichés.',
  palette: { primary: '#c8a46a', secondary: '#b3a794', tint: '#1f1a15', dark: '#16120e', heading: '#f3ece0', body: '#b3a794' },
  designNotes: 'Luxe design language: warm near-black backgrounds, ivory text, a restrained gold accent, Cormorant Garamond headlines, Jost body, hairline gold rules and square-cornered photography.',
};

const BRAND_FACTS =
  'Halden Row Interiors, 22 Halden Row, Suite 3, Charleston, SC 29401. Phone (843) 555-0132. hello@haldenrow.studio. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'projects', roleLabel: 'Projects' },
  { role: 'services', roleLabel: 'Services' },
  { role: 'process', roleLabel: 'Process' },
  { role: 'about', roleLabel: 'The Studio' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'interior_design', style: 'luxe', color: 'gold', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'halden-row-interior-design-theme';
const PACK_TITLE = 'Halden Row: Luxury Interior Design Studio Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for an interior design studio, architect or boutique hospitality brand, ready to make ' +
  'your own. Home, Projects, Services, Process, The Studio and Contact share one quiet, expensive identity: warm near-black ' +
  'backgrounds, ivory type, a restrained gold accent, a tall serif for headlines and hairline rules. Every section is built ' +
  'from proven, validated recipes and a single design language and style kit, so buttons, accordions, forms and type match ' +
  'on every page, on desktop, tablet and phone. A portfolio grid, a project gallery, services with fixed-fee pricing, a ' +
  'step-by-step process, a studio story and team, FAQs and an enquiry form with the studio details are all in place. ' +
  'Projects, prices, names and reviews are sample copy: swap in your own and publish. No lorem ipsum, no broken layouts. ' +
  'One simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Halden Row: Luxury Interior Design Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page Divi 5 website theme for an interior design studio: Home, Projects, Services, Process, The Studio ' +
    'and Contact. One luxe brand, real copy, portfolio, pricing and enquiry sections.',
  keywords: [
    'divi 5 interior design theme', 'interior designer website template', 'divi architecture studio template',
    'luxury divi 5 theme', 'interior design divi website', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Halden Row pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
